/// The declared cardinality of one element, or `None` when the type does not
/// declare it.
pub fn element_meta(owner: &str, name: &str) -> Option<&'static ElementMeta> {
    let found = ELEMENTS
        .binary_search_by(|row| (row.owner, row.name).cmp(&(owner, name)))
        .ok()?;
    Some(&ELEMENTS[found])
}
